// 排序後統計每個數的次數，再依次數由大到小排序取前 k 個
// 時間複雜度: O(n log n)，空間複雜度: O(n)
typedef struct { int val, freq; } Pair;

static int cmpInt(const void* a, const void* b) {
    int x = *(const int*)a, y = *(const int*)b;
    return (x > y) - (x < y);
}

static int cmpFreq(const void* a, const void* b) {
    return ((const Pair*)b)->freq - ((const Pair*)a)->freq;   // 次數由大到小
}

int* topKFrequent(int* nums, int numsSize, int k, int* returnSize) {
    qsort(nums, numsSize, sizeof(int), cmpInt);
    Pair* pairs = malloc(sizeof(Pair) * numsSize);
    int cnt = 0;
    for (int i = 0; i < numsSize; ) {
        int j = i;
        while (j < numsSize && nums[j] == nums[i]) j++;
        pairs[cnt].val = nums[i];
        pairs[cnt++].freq = j - i;
        i = j;
    }
    qsort(pairs, cnt, sizeof(Pair), cmpFreq);

    int* result = malloc(sizeof(int) * k);
    for (int i = 0; i < k; i++) result[i] = pairs[i].val;
    free(pairs);
    *returnSize = k;
    return result;
}

